function postProcessMindmapMarkdown(content, chapters, encodedNotePath) {
  const rawLines = content.split("\n");
  const expandedLines = [];
  for (let i = 0; i < rawLines.length; i++) {
    const line = rawLines[i];
    const m = line.match(/^(\s*)([-*+]\s+)(?:\*\*([^*:：]{2,16})\*\*\s*[:：]\s*|([^$*~:：]{2,12})\s*：\s*)(.+)$/);
    if (m) {
      const indent = m[1];
      const bullet = m[2];
      const label = (m[3] || m[4] || "").trim();
      const body = m[5].trim();
      let hasChild = false;
      for (let j = i + 1; j < rawLines.length; j++) {
        if (rawLines[j].trim() === "")
          continue;
        const nm = rawLines[j].match(/^(\s*)([-*+]\s+)/);
        if (nm && nm[1].length > indent.length)
          hasChild = true;
        break;
      }
      if (!hasChild && label && body) {
        expandedLines.push(`${indent}${bullet}**${label}**`);
        expandedLines.push(`${indent}  - ${body}`);
        continue;
      }
    }
    expandedLines.push(line);
  }
  const lines = expandedLines;
  for (let i = 0; i < lines.length - 1; i++) {
    const line = lines[i];
    const match = line.match(/^(\s*)([-*+]\s+)(.*)$/);
    if (match) {
      const currentIndent = match[1].length;
      let isParent = false;
      for (let j = i + 1; j < lines.length; j++) {
        const nextLine = lines[j];
        if (nextLine.trim() === "")
          continue;
        const nextMatch = nextLine.match(/^(\s*)([-*+]\s+)(.*)$/);
        if (nextMatch) {
          const nextIndent = nextMatch[1].length;
          if (nextIndent > currentIndent) {
            isParent = true;
          }
          break;
        } else if (nextLine.match(/^#+\s/)) {
          break;
        } else {
          const textIndentMatch = nextLine.match(/^(\s*)/);
          const textIndent = textIndentMatch ? textIndentMatch[1].length : 0;
          if (textIndent <= currentIndent) {
            break;
          }
        }
      }
      if (isParent) {
        let text = match[3];
        text = text.replace(/\*\*/g, "");
        lines[i] = `${match[1]}${match[2]}**${text}**`;
      }
    }
  }
  content = lines.join("\n");
  const nodeRegex = /^(#+)\s*\[\s*(\d{1,3}:\d{2}(?::\d{2})?)\s*\]\s*(.*)$/gm;
  content = content.replace(nodeRegex, (match, hashes, rawTimestamp, displayTitle) => {
    const tsSec = parseTime(rawTimestamp);
    if (!Number.isFinite(tsSec))
      return match;
    const timestamp = formatTime(tsSec);
    const sameTimeChapters = chapters.filter((c) => c.timestamp === timestamp);
    const originalChapter = sameTimeChapters.length > 1 ? pickBestTitleMatch(sameTimeChapters, displayTitle) : sameTimeChapters[0];
    const realTitle = originalChapter ? originalChapter.title : displayTitle.trim();
    const targetHeading = `\u23F1\uFE0F ${timestamp} ${realTitle}`;
    const encodedHeading = encodeURIComponent(targetHeading);
    let cleanDisplayTitle = displayTitle.trim();
    if (!cleanDisplayTitle.startsWith("\u{1F4CC}")) {
      cleanDisplayTitle = `\u{1F4CC}${cleanDisplayTitle}`;
    }
    return `${hashes} <a href="obsidian://silicon-jump?file=${encodedNotePath}&heading=${encodedHeading}">${cleanDisplayTitle}</a>`;
  });
  return content;
}
function pickBestTitleMatch(candidates, displayTitle) {
  const bigrams = (s) => {
    const out = /* @__PURE__ */ new Set();
    for (let i = 0; i < s.length - 1; i++)
      out.add(s.slice(i, i + 2));
    return out;
  };
  const target = displayTitle.replace(/^📌/, "").replace(/[\s*`\\()[\]（）【】:：、，。!！?？"'“”‘’\-—]/g, "").toLowerCase();
  let best = candidates[0];
  let bestScore = -1;
  for (const c of candidates) {
    const t = c.title.replace(/^📌/, "").replace(/[\s*`\\()[\]（）【】:：、，。!！?？"'“”‘’\-—]/g, "").toLowerCase();
    let score;
    if (t.length > 0 && t === target)
      score = 3;
    else if (target.length > 1 && (t.includes(target) || target.includes(t)))
      score = 2;
    else {
      const ta = bigrams(target);
      const tb = bigrams(t);
      let inter = 0;
      for (const x of ta)
        if (tb.has(x))
          inter++;
      const union = ta.size + tb.size - inter;
      score = union > 0 ? inter / union : 0;
    }
    if (score > bestScore) {
      bestScore = score;
      best = c;
    }
  }
  return best;
}
